SELECT id, user_id, title, content, start_date, end_date, status FROM t_health_plan  AND id = #{id}
 AND user_id = #{userId}
 AND title LIKE CONCAT('%', #{title}, '%')
 AND start_date = #{startDate}
 AND end_date = #{endDate}
 AND status LIKE CONCAT('%', #{status}, '%') ORDER BY id DESC
